#include <iostream>
#include <queue>
using namespace std;

int main() {
    int number;
    cin >> number;
    cin.ignore();

    queue<int> queue;
    bool in_order = true;
    int result = 0;

    for (int i = 0; i < 2 * number; i++) {
        string input_str;
        getline(cin, input_str);
        string operation[3];
        int j = 0;
        for (char c : input_str) {
            if (c == ' ') {
                j++;
            } else {
                operation[j] += c;
            }
        }
        if (operation[0] == "head") {
            if (!queue.empty() && in_order) {
                in_order = false;
            }
            queue.push(stoi(operation[2]));
        } else if (operation[0] == "tail") {
            queue.push(stoi(operation[2]));
        } else {
            if (queue.empty()) {
                continue;
            }
            if (!in_order) {
                result++;
                in_order = true;
            }
            queue.pop();
        }
    }

    cout << result << endl;
    return 0;
}


